export const TOTAL_ROWS = 15;
export const TOTAL_COLUMNS = 24;
export const MAX_SEATS_PER_BOOKING = 10;
export const COUCH_ROW = 15;
export const COUCH_PRICE = 89;

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): { row: number; column: number } {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) throw new Error(`Invalid seat id: ${id}`);
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function isAccessible(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

export function seatPrice(row: number): number {
  if (row <= 5) return 25;
  if (row <= 10) return 32;
  return 39;
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export interface BookingItem {
  row: number;
  kind: 'seat' | 'couch';
  column?: number;
  columnStart?: number;
  columnEnd?: number;
  price: number;
  ids: string[];
}

/** Groups selected seat identifiers into seats/couches, ordered by row then column. */
export function groupBookingSeats(ids: string[]): BookingItem[] {
  const byRow = new Map<number, number[]>();
  for (const id of ids) {
    const { row, column } = parseSeatId(id);
    const columns = byRow.get(row);
    if (columns) columns.push(column);
    else byRow.set(row, [column]);
  }

  const items: BookingItem[] = [];
  const rows = [...byRow.keys()].sort((a, b) => a - b);
  for (const row of rows) {
    const columns = [...byRow.get(row)!].sort((a, b) => a - b);
    if (row === COUCH_ROW) {
      for (let i = 0; i < columns.length; i += 2) {
        const start = columns[i];
        const end = columns[i + 1];
        items.push({
          row,
          kind: 'couch',
          columnStart: start,
          columnEnd: end,
          price: COUCH_PRICE,
          ids: [seatId(row, start), seatId(row, end)],
        });
      }
    } else {
      for (const column of columns) {
        items.push({
          row,
          kind: 'seat',
          column,
          price: seatPrice(row),
          ids: [seatId(row, column)],
        });
      }
    }
  }
  return items;
}

import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toSignal } from '@angular/core/rxjs-interop';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { ActivatedRoute, Data, Router } from '@angular/router';
import { ApiService } from '../../core/api.service';
import { BookingService, CheckoutFormValues } from '../../core/booking.service';
import { emailFormatValidator, matchesControlValidator, phoneFormatValidator } from '../../core/checkout-validators';
import { ReservationRequest } from '../../core/models';
import { ScreeningData } from '../../core/screening-resolver';
import { formatPrice, groupBookingSeats } from '../../core/seats';
import { ToastService } from '../../core/toast.service';

@Component({
  selector: 'app-checkout',
  imports: [ReactiveFormsModule, MatButtonModule, MatFormFieldModule, MatInputModule, MatCheckboxModule],
  templateUrl: './checkout.component.html',
  styleUrl: './checkout.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CheckoutComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly booking = inject(BookingService);
  private readonly api = inject(ApiService);
  private readonly toast = inject(ToastService);
  private readonly fb = inject(FormBuilder);

  private readonly routeData = toSignal(this.route.data, { requireSync: true }) as () => Data;
  protected readonly screening = computed(() => (this.routeData()['data'] as ScreeningData).screening);

  protected readonly submitting = signal(false);

  protected readonly total = computed(() =>
    groupBookingSeats(this.booking.booking()?.seats ?? []).reduce((sum, item) => sum + item.price, 0),
  );

  private readonly initialValues: CheckoutFormValues = this.booking.booking()?.form ?? {
    firstName: '',
    lastName: '',
    email: '',
    confirmEmail: '',
    phone: '',
    terms: false,
  };

  protected readonly form = this.fb.nonNullable.group({
    firstName: [this.initialValues.firstName, [Validators.required, Validators.minLength(2)]],
    lastName: [this.initialValues.lastName, [Validators.required, Validators.minLength(2)]],
    email: [this.initialValues.email, [Validators.required, emailFormatValidator()]],
    confirmEmail: [this.initialValues.confirmEmail, [Validators.required, matchesControlValidator('email')]],
    phone: [this.initialValues.phone, [phoneFormatValidator()]],
    terms: [this.initialValues.terms, [Validators.requiredTrue]],
  });

  constructor() {
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe((value) => {
      this.booking.updateForm(value as CheckoutFormValues);
    });

    this.form.controls.email.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => {
      this.form.controls.confirmEmail.updateValueAndValidity({ onlySelf: true });
    });
  }

  protected errorMessage(name: keyof typeof this.form.controls): string | null {
    const control = this.form.controls[name];
    if (!control.touched || !control.errors) return null;
    const errors = control.errors;
    if (errors['required']) {
      return name === 'terms' ? 'You must accept the terms and conditions' : `${this.labelFor(name)} is required`;
    }
    if (errors['minlength']) return `${this.labelFor(name)} must be at least 2 characters`;
    if (errors['emailFormat']) return 'Enter a valid email address';
    if (errors['mismatch']) return 'Email addresses do not match';
    if (errors['phoneFormat']) return 'Phone number must be exactly 9 digits';
    return null;
  }

  private labelFor(name: string): string {
    const labels: Record<string, string> = {
      firstName: 'First name',
      lastName: 'Last name',
      email: 'Email',
      confirmEmail: 'Confirm email',
    };
    return labels[name] ?? name;
  }

  protected price(amount: number): string {
    return formatPrice(amount);
  }

  protected onTermsChange(): void {
    this.form.controls.terms.markAsTouched();
  }

  protected back(): void {
    this.router.navigate(['/screenings', this.screening().id, 'summary']);
  }

  protected pay(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      this.toast.show('The form contains errors');
      return;
    }

    this.submitting.set(true);
    const value = this.form.getRawValue();
    const seats = groupBookingSeats(this.booking.booking()!.seats).flatMap((item) => item.ids);
    const payload: ReservationRequest = {
      screeningId: this.screening().id,
      seats,
      customer: {
        firstName: value.firstName,
        lastName: value.lastName,
        email: value.email,
        phone: value.phone,
      },
      totalPrice: this.total(),
    };

    this.api.createReservation(payload).subscribe({
      next: () => {
        this.submitting.set(false);
        this.booking.markPaid(value.email);
        this.router.navigateByUrl('/confirmation');
      },
      error: () => {
        this.submitting.set(false);
        this.toast.show('Payment failed. Please try again.');
      },
    });
  }
}

import { ChangeDetectionStrategy, Component, computed, effect, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { forkJoin } from 'rxjs';
import { ApiService } from '../../core/api.service';
import { resolveSelectedDate, toIsoDate } from '../../core/date-utils';
import { Movie, Screening } from '../../core/models';
import { DayPickerComponent } from './day-picker.component';

interface MovieWithScreenings {
  movie: Movie;
  screenings: Screening[];
}

type LoadStatus = 'loading' | 'error' | 'loaded';

@Component({
  selector: 'app-movie-list',
  imports: [DayPickerComponent, MatButtonModule],
  templateUrl: './movie-list.component.html',
  styleUrl: './movie-list.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MovieListComponent {
  private readonly api = inject(ApiService);
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);

  private readonly queryParamMap = toSignal(this.route.queryParamMap, { requireSync: true });

  protected readonly selectedDate = computed(() => resolveSelectedDate(this.queryParamMap().get('date')));
  private readonly selectedDateIso = computed(() => toIsoDate(this.selectedDate()));

  protected readonly status = signal<LoadStatus>('loading');
  protected readonly movies = signal<MovieWithScreenings[]>([]);

  constructor() {
    effect(() => {
      this.load(this.selectedDateIso());
    });
  }

  private load(date: string): void {
    this.status.set('loading');
    forkJoin([this.api.getMovies(), this.api.getScreeningsByDate(date)]).subscribe({
      next: ([movies, screenings]) => {
        const screeningsByMovie = new Map<number, Screening[]>();
        for (const screening of screenings) {
          const list = screeningsByMovie.get(screening.movieId);
          if (list) list.push(screening);
          else screeningsByMovie.set(screening.movieId, [screening]);
        }
        this.movies.set(
          movies
            .filter((movie) => screeningsByMovie.has(movie.id))
            .map((movie) => ({
              movie,
              screenings: [...screeningsByMovie.get(movie.id)!].sort((a, b) => a.time.localeCompare(b.time)),
            })),
        );
        this.status.set('loaded');
      },
      error: () => this.status.set('error'),
    });
  }

  protected onDateSelected(date: Date): void {
    this.router.navigate([], { relativeTo: this.route, queryParams: { date: toIsoDate(date) } });
  }

  protected retry(): void {
    this.load(this.selectedDateIso());
  }

  protected openSeatMap(screeningId: number): void {
    this.router.navigate(['/screenings', screeningId, 'seats']);
  }
}
